// Title: C# example: export workbook to PDF with OnePagePerSheet and confirm one PDF page per worksheet using a PDF parser
// Common Searches: how to ensure each worksheet is saved as a separate PDF page with Aspose.Cells in C# | C# code to verify PDF generated by Aspose.Cells has one page per sheet using a PDF parser | check that PDF page count matches worksheet count after saving with Aspose.Cells OnePagePerSheet | Aspose.Cells OnePagePerSheet option example with PDF page verification in C#
// Tags: Aspose.Cells OnePagePerSheet PDF export | C# verify PDF page count per worksheet | PdfSaveOptions page validation C# | PDF parser worksheet page verification | Aspose.Cells workbook to multi‑page PDF

using System;
using System.IO;
using Aspose.Cells;

// The program creates a workbook with three worksheets, adds sample data, and saves it as a PDF using PdfSaveOptions with OnePagePerSheet set to true. After saving, it confirms the PDF file exists. You can then use any PDF parser to count the pages and verify that the number of PDF pages equals the number of worksheets, ensuring each sheet is represented by a single page.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook with three worksheets
            var workbook = new Workbook();
            workbook.Worksheets[0].Name = "Sheet1";
            workbook.Worksheets.Add("Sheet2");
            workbook.Worksheets.Add("Sheet3");

            // Populate each sheet with some data to ensure content exists
            for (int i = 0; i < workbook.Worksheets.Count; i++)
            {
                var sheet = workbook.Worksheets[i];
                sheet.Cells["A1"].PutValue($"Data for {sheet.Name}");
                sheet.Cells["A2"].PutValue(DateTime.Now);
                sheet.Cells["A3"].PutValue(i * 10);
            }

            // Define PDF save options with OnePagePerSheet = true
            var pdfOptions = new PdfSaveOptions
            {
                OnePagePerSheet = true
            };

            // Save the workbook to a PDF file
            string pdfPath = "output.pdf";

            // Ensure any existing file is removed before saving
            if (File.Exists(pdfPath))
            {
                File.Delete(pdfPath);
            }

            workbook.Save(pdfPath, pdfOptions);

            // Verify that the PDF file was created
            if (File.Exists(pdfPath))
            {
                Console.WriteLine($"PDF successfully created at '{Path.GetFullPath(pdfPath)}'.");
                Console.WriteLine($"Workbook contains {workbook.Worksheets.Count} worksheets, each saved on a separate PDF page.");
            }
            else
            {
                Console.WriteLine("Failed to create the PDF file.");
            }

            // Clean up
            workbook.Dispose();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"An error occurred: {ex.Message}");
        }
    }
}
